data.query:
query ($huWhere: HandlingUnitWhereInput, $invWhere: InventoryWhereInput) {
  inventory(where: $invWhere) {
    total
    edges {
      node {
        id
        serialNumber
        active
        inventoryStatusId
        shippable
        product {
          id
          number
          allowPickOverage
        }
        quantity {
          value
        }
        product {
          id
          code
        }
        handlingUnit {
          id
          loadId
        }
        inventoryPickSteps {
          edges {
            node {
              id
              picked
              pickStep {
                id
                pick {
                  loadId
                }
                quantity {
                  value
                  unitId
                }
                orderLineRelease {
                  quantity {
                    value
                    unitId
                  }
                  shipmentLines {
                    total
                    edges {
                      node {
                        id
                        quantity {
                          value
                          unitId
                        }
                        packedQuantity {
                          value
                          unitId
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  handlingUnit(where: $huWhere) {
    total
    edges {
      node {
        id
        serialNumber
        barcode
        inventory: inventories(where: $invWhere) {
          total
          edges {
            node {
              id
              serialNumber
              product {
                id
                number
                allowPickOverage
              }
              quantity {
                value
              }
              product {
                id
                code
              }
              handlingUnit {
                id
                loadId
              }
              inventoryPickSteps {
                edges {
                  node {
                    id
                    picked
                      pickStep {
                        quantity {
                          value
                          unitId
                        }
                        orderLineRelease {
                          quantity {
                            value
                            unitId
                          }
                          shipmentLines {
                            total
                            edges {
                              node {
                                id
                                quantity {
                                  value
                                  unitId
                                }
                                packedQuantity {
                                  value
                                  unitId
                                }
                              }
                            }
                          }
                        }
                      }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

branches.transform:
(
  $invPicked := $state.context.serial.inventory.edges.node.inventoryPickSteps.edges.node.picked;
  $huPicked := $state.context.serial.handlingUnit.edges.node.inventoryPickSteps.edges.node.picked;

  $invPicked_safe := $invPicked != null ? $invPicked : false;
  $huPicked_safe := $huPicked != null ? $huPicked : false;

  $invPicked_safe = false and $huPicked_safe = false
)

(
  $inv := $state.context.serial.inventory.edges[0].node;
  $hu := $state.context.serial.handlingUnit.edges[0].node.inventory.edges[0].node;

  $node := $inv != null ? $inv : $hu;

  $shipmentLine := $node.inventoryPickSteps.edges[0].node.pickStep.orderLineRelease.shipmentLines.edges[0].node;
  $orderLineReleaseQty := $node.inventoryPickSteps.edges[0].node.pickStep.orderLineRelease.quantity.value;

  $allowPickOverage := $node.product.allowPickOverage = true;
  $invQty := $node.quantity.value != null ? $node.quantity.value : 0;
  $orderLineReleaseQty := $orderLineReleaseQty != null ? $orderLineReleaseQty : 0;
  $packedQty := $shipmentLine.packedQuantity.value != null ? $shipmentLine.packedQuantity.value : 0;

  $allowPickOverage ? false : $packedQty + $invQty > $orderLineReleaseQty
)

data.transform:
(
  $serialType := $state.context.serialType;
  $inventoryNode := $serialType = "inventory" ?
    $state.context.serial.inventory.edges[0].node
    :
    $state.context.serial.handlingUnit.edges[0].node.inventory.edges[0].node;

  $shipmentLines := $inventoryNode.inventoryPickSteps.edges[0].node.pickStep.orderLineRelease.shipmentLines;
  $inventoryQty := $inventoryNode.quantity.value;

  $total := $shipmentLines.total;

  $findLine := function($lines, $idx) {
    $idx >= $count($lines) ? null :
    (
      $line := $lines[$idx];
      $packedQty := $exists($line.packedQuantity) and $line.packedQuantity != null ? $line.packedQuantity.value : 0;
      $fits := ($packedQty + $inventoryQty) <= $line.quantity.value;
      $fits ? $line.id : $findLine($lines, $idx + 1)
    )
  };

  $eligibleLines := $shipmentLines.edges.node[
    $not($exists(packedQuantity)) or packedQuantity = null or packedQuantity.value < quantity.value
  ];

  $shipmentLineId := $total = 0 ? null : $findLine($eligibleLines, 0);

  {
    "shipmentLine": 
      {
        "found": $shipmentLineId != null,
        "id": $shipmentLineId
      }
  }
)

data.mutation:
mutation(
  $inventoryPayload: [InventoryUpdatePayloadInput!]!,
  $shipmentLinePayload: [ShipmentLineUpdatePayloadInput!]!,
  $pickStepInvPayload: [InventoryPickStepUpdatePayloadInput!]!
)
{
  updateInventory(payload: $inventoryPayload){ id }
  updateShipmentLine(payload:  $shipmentLinePayload ){ id }
  updateInventoryPickStep(payload: $pickStepInvPayload) { id }
}

data.query:
query Load($where: LoadWhereInput, $orderBy: [LoadOrderByInput!], $first: Int, $after: String) {
  load(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
      }
    }
  }
}

data.transform:
{
  "title": "Serial Not Found",
  "message": "The scanned serial number (" & $state.context.input.serial & ") could not be found."
}

{
  "title": "Pick Not Complete",
  "message": "Picking is not completed for the scanned serial number."
}

{
  "title": "Serial Already Packed",
  "message": "The scanned serial number is already packed."
}

{
  "title": "Inventory is Not Active",
  "message": "The scanned inventory is not active and cannot be packed."
}

{
  "title": "Serial Inventory Status",
  "message": "The inventory status is '" & inventory.edges.node.inventoryStatusId & "' and is not able to be packed."
}

{
  "title": "No Shipment Lines",
  "message": "No lines for this shipment were found."
}

{
  "title": "Pack Quantity Exceeded",
  "message": "The scanned serial would exceed the order quantity plus the packed quantity."
}

{
  "title": "No Shipment Line Found",
  "message": "No shipment line was found tied to the scanned serial number."
}

{
  "title": "Serial Not Shippable",
  "message": "The scanned serial is not shippable and cannot be packed."
}

(
  $type:= $isNotNilOrEmpty($state.context.input.orderId) ? "Order": "Load";
  $number:= $isNotNilOrEmpty($state.context.input.orderId) ? $state.context.input.orderId: $state.context.input.loadId;

  {
    "title": "Serial Not in " & $type,
    "message": "The scanned serial number (" & $state.context.input.serial & ") is not part of " & $type & " " & $number
  }
)

